-- =====================================================================
-- E-Library: akun pegawai & staf (login dengan NIP 18 digit atau NIK 16 digit)
-- + data guru dari DATA KEPEGAWAIAN 2026 (113 orang ber-NIP)
-- Jalankan SEKALI di phpMyAdmin (tab SQL), SETELAH file aktivasi_nis.sql.
-- CADANGKAN database dulu (Export).
--
-- Kalau versi lama file ini (kolom `nik`) SUDAH terlanjur dijalankan, jalankan dulu:
--   DROP TABLE IF EXISTS `staffs`;
--   ALTER TABLE `users` DROP INDEX `users_nik_unique`, DROP COLUMN `nik`;
--   DELETE FROM `migrations` WHERE `migration` LIKE '2026_11_06_000001%';
-- =====================================================================

SET NAMES utf8mb4;

ALTER TABLE `users`
  ADD COLUMN `staff_number` varchar(20) NULL AFTER `nis`,
  ADD UNIQUE KEY `users_staff_number_unique` (`staff_number`);

CREATE TABLE `staffs` (
  `staff_number` varchar(20) NOT NULL,
  `name` varchar(255) NOT NULL,
  `gender` varchar(1) DEFAULT NULL,
  `religion` varchar(30) DEFAULT NULL,
  `position` varchar(255) NOT NULL,
  `employment_status` varchar(50) DEFAULT NULL,
  `nip` varchar(30) DEFAULT NULL,
  `rank_name` varchar(255) DEFAULT NULL,
  `grade` varchar(20) DEFAULT NULL,
  `unit` varchar(255) DEFAULT NULL,
  `phone` varchar(30) DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  `activation_status` varchar(20) NOT NULL DEFAULT 'inactive',
  `activation_password` varchar(255) DEFAULT NULL,
  `activation_requested_at` timestamp NULL DEFAULT NULL,
  `activated_at` timestamp NULL DEFAULT NULL,
  `activation_note` varchar(255) DEFAULT NULL,
  `user_id` bigint(20) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`staff_number`),
  KEY `staffs_activation_status_index` (`activation_status`),
  KEY `staffs_user_id_foreign` (`user_id`),
  CONSTRAINT `staffs_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


